        } catch {
            getterOk = false;
        }

        // The universal property: when the getter returns (no revert), the returned value equals the stored value that would be set by initialize (or 0 if initialize failed).
        // The mutant that multiplies the stored _positionFee by 2 will violate this for some positionFee inputs (e.g., any non-zero positionFee when initialize succeeds).

        // We assert the property only when the getter completed (so we read actual behavior). This single assertion must hold for reference and be violated by the mutant.
        assertTrue(getterOk && got == expected);
    }
}

