    function testFuzz_property(uint256 maintenanceRaw, uint256 fundingFeeRaw, uint256 makerFeeRaw, uint256 takerFeeRaw, uint256 positionFeeRaw, uint256 makerLimitRaw, bytes32 nameHash, bytes32 symbolHash, address oracleAddr) public {
        // Keep values wide but bounded to reasonable UFixed18 range (multiples of 1e18 internally expected)
        uint256 MAX = type(uint256).max / 1e18;
        maintenanceRaw = maintenanceRaw % (MAX == 0 ? 1 : MAX);
        fundingFeeRaw = fundingFeeRaw % (MAX == 0 ? 1 : MAX);
        makerFeeRaw = makerFeeRaw % (MAX == 0 ? 1 : MAX);
        takerFeeRaw = takerFeeRaw % (MAX == 0 ? 1 : MAX);
        positionFeeRaw = positionFeeRaw % (MAX == 0 ? 1 : MAX);
        makerLimitRaw = makerLimitRaw % (MAX == 0 ? 1 : MAX);

        // build minimal JumpRateUtilizationCurve with zeros (we only need to pass some struct)
        // Construct bytes30 data for PayoffDefinition using name/symbol hashes (not used by tested getter)
        bytes30 emptyBytes30 = bytes30(0);

        // Compose ProductInfo via ABI-encoded call to C.initialize is done by calling initialize directly.
        // But constructing C.ProductInfo in solidity test requires the type; instead call initialize with the appropriate tuple shape.

        // Build ProductInfo local variables matching declaration in C (we rely on positional tuple in call)
        string memory name = string(abi.encodePacked(nameHash));
        string memory symbol = string(abi.encodePacked(symbolHash));

        // Build PayoffDefinition struct arg: (PayoffType, PayoffDirection, bytes30) - we can pass zeros because C only validates payoffDefinition_.valid() in __UPayoffProvider__initialize,
        // but to avoid dependence on validity, we create a minimal valid-looking PayoffDefinition by low-level ABI encoding of the expected calldata for initialize.
        // To avoid complexity, we will simply skip calling initialize if oracleAddr is zero (invalid contract), else we will deploy a tiny dummy oracle contract and pass it.

        if (oracleAddr == address(0)) {
            // if fuzz gave zero address, use a freshly deployed minimal oracle to satisfy Address.isContract checks
            DummyOracle o = new DummyOracle();
            oracleAddr = address(o);
        } else {
            // ensure oracleAddr is a contract (deploy a dummy and use its address mapping if the fuzzed addr is EOA)
            // We cannot deploy at arbitrary address; instead always deploy a dummy and ignore incoming address
            DummyOracle o = new DummyOracle();
            oracleAddr = address(o);
        }

        // Build UFixed18 typed values by calling UFixed18Lib.from(uint256) is internal; we cannot construct the type directly here.
        // However, initialize expects the tuple ProductInfo; solidity will accept (string,string,(...),address,uint256,uint256,...) where the UFixed18 type in the callee is ABI-compatible with uint256.
        // So we can pass raw uint256 scaled by 1e18 to represent UFixed18 values.

        uint256 scale = 1e18;
        uint256 maintenance = maintenanceRaw * scale;
        uint256 fundingFee = fundingFeeRaw * scale;
        uint256 makerFee = makerFeeRaw * scale;
        uint256 takerFee = takerFeeRaw * scale;
        uint256 positionFee = positionFeeRaw * scale;
        uint256 makerLimit = makerLimitRaw * scale;

        // Construct a minimal JumpRateUtilizationCurve tuple: (int128 minRate, int128 maxRate, int128 targetRate, uint128 targetUtilization)
        int128 minRate = 0;
        int128 maxRate = 0;
        int128 targetRate = 0;
        uint128 targetUtilization = 0;

        // Now perform initialize via low-level call to avoid solidity type mismatch for UFixed18; use abi.encodeWithSelector
        bytes memory payoffDefinitionEncoded = abi.encode(uint8(0), uint8(0), emptyBytes30);

        bytes memory utilizationCurveEncoded = abi.encodePacked(minRate, maxRate, targetRate, targetUtilization);

        bytes memory productInfoEncoded = abi.encode(
            name,
            symbol,
            // payoffDefinition (we inline its fields as a tuple matching calldata layout)
            // The initialize signature expects (ProductInfo calldata)
            // Build ProductInfo as tuple: (string,string,PayoffDefinition,address,uint256,uint256,uint256,uint256,uint256,uint256, (JumpRateUtilizationCurve))
            // We'll encode the full tuple by manual concatenation
            // Simpler: call C.initialize with a tuple constructed in Solidity; the compiler will accept uint256 for UFixed18 params because underlying ABI is uint256.
            // So instead we cast the calldata-friendly types directly.
            // Build the PayoffDefinition as a tuple struct in memory using the defined types via a helper internal call is not possible; so we will call initialize via a typed call in solidity.
            // Therefore revert to a typed local struct emulation by creating local variables matching types and calling initialize directly.

            // No-op placeholder; actual call done below
            ""
        );

        // Because constructing the ProductInfo struct inline is feasible, do that directly using the field order.
        C.ProductInfo memory pi = C.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: emptyBytes30}),
            oracle: IOracleProvider(oracleAddr),
            maintenance: UFixed18.wrap(maintenance),
            fundingFee: UFixed18.wrap(fundingFee),
            makerFee: UFixed18.wrap(makerFee),
            takerFee: UFixed18.wrap(takerFee),
            positionFee: UFixed18.wrap(positionFee),
            makerLimit: UFixed18.wrap(makerLimit),
            utilizationCurve: JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)})
        });

        // However, above types like C.PayoffDefinitionLib etc are not visible; to avoid type errors, we must not reference internal library types.
        // Simpler approach: perform a low-level call to initialize with ABI-encoded ProductInfo tuple using expected layout. We'll craft calldata matching initialize(ProductInfo).

        // Build calldata manually for initialize(ProductInfo)
        // Function selector
        bytes4 sel = bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"));

        bytes memory payoffDef = abi.encode(uint8(0), uint8(0), emptyBytes30);
        bytes memory utilization = abi.encode(minRate, maxRate, targetRate, targetUtilization);

        bytes memory calldataInit = abi.encodeWithSelector(
            sel,
            name,
            symbol,
            payoffDef,
            oracleAddr,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            utilization
        );

        // call initialize; if it reverts, we skip this input as inadmissible
        (bool ok, ) = address(c).call(calldataInit);
        if (!ok) return; // admissibility filter: only consider inputs where initialize succeeds

        // Now query the positionFee getter; we must observe behavior via try/catch because mutant could revert (though it won't)
        bool returnedOk;
        uint256 reported;
        try c.positionFee() returns (uint256 v) {
            returnedOk = true;
            reported = v;
        } catch {
            // if getter reverts, treat as failure of admissibility and skip
            return;
        }

        // The general rule: reported == positionFee (the value we initialized). We assert that for all fuzz inputs, this holds in reference.
        // But we must express the assertion using only c's public surface. We have access to the stored value only via c.positionFee(), so assert equality to the scaled input.
        assertTrue(reported == positionFee, "positionFee() must return the initialized stored UFixed18 value");
    }
}

// Minimal DummyOracle to satisfy Address.isContract checks and provide required IOracleProvider interface minimally
interface IOracleProvider {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256) external view returns (OracleVersion memory);
    function sync() external returns (OracleVersion memory);
}

contract DummyOracle is IOracleProvider {
    function sync() external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
    function currentVersion() external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
    function atVersion(uint256) external pure returns (OracleVersion memory) { return OracleVersion({version: 1, timestamp: block.timestamp, price: 0}); }
}
